{"explanation": "The regex only matched digits (\d+) but not negative integers. Fixed by adding an optional minus sign (-?) before each digit group to allow negative values.", "patched_code": "import re


def parse_point(text):
    """Parse a point written as "(x, y)", where x and y are integers that may be negative,
    with optional spaces. Return the tuple (x, y) of ints, and raise ValueError when the
    text is not of that form.
    """
    match = re.fullmatch(r"\s*\(\s*(-?\d+)\s*,\s*(-?\d+)\s*\)\s*", text)
    if match is None:
        raise ValueError(f"not a point: {text!r}")
    return int(match.group(1)), int(match.group(2))"}

{"explanation": "When the input is '[]', body[1:-1] is an empty string, and ''.split(',') produces [''], causing int('') to raise ValueError. The fix checks if the inner content is empty (after stripping) and returns an empty list in that case.", "patched_code": "def parse_int_list(text):
    """Parse a list of integers written like "[4, -1, 7]".

    The text is a pair of square brackets around zero or more integers separated by commas;
    spaces are allowed anywhere. Return the integers as a list, and raise ValueError when the
    text is not of that form.
    """
    body = text.strip()
    if not (body.startswith("[") and body.endswith("]")):
        raise ValueError(f"not a list: {text!r}")
    inner = body[1:-1].strip()
    if not inner:
        return []
    return [int(part) for part in inner.split(",")]"}

